import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题"},"headers":[],"relativePath":"ip-network/dual-isp-dia/faq.md","filePath":"ip-network/dual-isp-dia/faq.md","lastUpdated":1793693502000}'),r={name:"ip-network/dual-isp-dia/faq.md"};function n(l,a,d,p,s,u){return t(),i("div",null,[...a[0]||(a[0]=[o('<h3 id="什么是双isp-dia-家庭属性ip" tabindex="-1">什么是双ISP DIA（家庭属性IP）？ <a class="header-anchor" href="#什么是双isp-dia-家庭属性ip" aria-label="Permalink to &quot;什么是双ISP DIA（家庭属性IP）？&quot;">​</a></h3><p>双ISP DIA 指 IP 的 ASN Type与Company Type均为 ISP（运营商）的专线接入 IP。与机房（数据中心）IP 相比，它的网络属性更接近普通用户的上网环境，因此部分平台会对这类 IP 采取更宽松的访问策略。</p><h3 id="能保证-tiktok、youtube、netflix-等平台不受限制吗" tabindex="-1">能保证 TikTok、YouTube、Netflix 等平台不受限制吗？ <a class="header-anchor" href="#能保证-tiktok、youtube、netflix-等平台不受限制吗" aria-label="Permalink to &quot;能保证 TikTok、YouTube、Netflix 等平台不受限制吗？&quot;">​</a></h3><p>无法保证。平台的识别和风控策略由第三方制定，并会不断调整。双ISP DIA 能使被平台限制的概率低于普通机房 IP，具体效果还取决于平台策略、账号状态、使用方式等因素。</p><h3 id="为什么我查询到的结果与介绍不完全一致" tabindex="-1">为什么我查询到的结果与介绍不完全一致？ <a class="header-anchor" href="#为什么我查询到的结果与介绍不完全一致" aria-label="Permalink to &quot;为什么我查询到的结果与介绍不完全一致？&quot;">​</a></h3><p>不同 IP 数据库的识别标准不同，且数据更新存在延迟，同一 IP 在不同数据库中的分类可能不一致。如果您查询到的 IP 类型显示为 Hosting，请联系客服，我们会协助核实。</p><h3 id="裸机云和物理服务器有什么区别" tabindex="-1">裸机云和物理服务器有什么区别？ <a class="header-anchor" href="#裸机云和物理服务器有什么区别" aria-label="Permalink to &quot;裸机云和物理服务器有什么区别？&quot;">​</a></h3><p>裸机云具备物理服务器的硬件性能，同时拥有云服务器的便捷管理方式，适合需要快速上线、灵活调整的业务。物理服务器为完整独享的物理资源，适合对性能、稳定性和独立环境要求更高的业务。</p>',8)])])}const c=e(r,[["render",n]]);export{h as __pageData,c as default};
